import React from 'react'
import { Row, Button } from 'antd'
import { connect } from 'react-redux'
import LayoutContentWrapper from '../../../../components/utility/layoutWrapper'
import LayoutContent from '../../../../components/utility/layoutContent'
import TableWrapper from '../pagination.style'
import claimActions from '../../../redux/claims/actions'
import DeleteAddOns from '../deleteAddOnsModal'
import AddEditAddOns from '../addEditAddOns'
import Delete from '../../../../image/delete-icon.png'
import Edit from '../../../../image/edit-button.png'

const { getAddOnsQuestionnaireList } = claimActions

class AddOns extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      addOnsQuestionsList: [],
      showdeleteAddOnsModal: false,
      showAddDeleteAddOnsModal: false,
      currQuestionsData: [],
      isEdit: false,
      page: 1,
      pageSize: 10
    }
  }

  fetch = (params = {}) => {
    const { page: pageParam, page_size: pageSizeParam } = params
    const page = Number(pageParam) || 1
    const pageSize = Number(pageSizeParam) || 10
    this.setState({ page_size: pageSize, page })

    this.props.getAddOnsQuestionnaireList({
      page,
      per_page: 10,
      sort_by: 'created_at'
    })
  };

  componentDidMount () {
    this.fetch()
  }

  handleDeleteAddonsModal = (val) => {
    this.setState({ showdeleteAddOnsModal: true, currQuestionsData: val })
  };

  handleCloseDeleteAddonsModal = () => {
    this.setState({ showdeleteAddOnsModal: false })
  };

  handleDeleteAddons = () => {
    const { page = 1, pageSize = 10 } = this.state
    this.setState({ showdeleteAddOnsModal: false })
    this.props.getAddOnsQuestionnaireList({
      page,
      page_size: pageSize,
      sort_by: 'created_at'
    })
  };

  handleEditAddonsModal = (val) => {
    this.setState({
      showAddDeleteAddOnsModal: true,
      currQuestionsData: val,
      isEdit: true
    })
  };

  handleCloseAddEditAddonsModal = () => {
    this.setState({ showAddDeleteAddOnsModal: false })
    this.setState({ isEdit: false })
  };

  handleSaveAddEditAddonsModal = () => {
    const { page = 1, pageSize = 10 } = this.state
    this.setState({ showAddDeleteAddOnsModal: false, isEdit: false })
    this.props.getAddOnsQuestionnaireList({
      page,
      page_size: pageSize,
      sort_by: 'created_at'
    })
  };

  handleAddAddonsModal = () => {
    this.setState({ showAddDeleteAddOnsModal: true })
  };

  handleTableChange = (pagination) => {
    const { pageSize, current } = pagination
    const finalFilter = {
      page: current,
      page_size: pageSize
    }
    this.setState({
      page: current,
      page_size: pageSize
    }, () => this.fetch(finalFilter))
  }

  render () {
    const {
      getAddOnsListsLoading,
      getAddOnsListsError,
      addOnsQuestionsList,
      addOnsMetaData: { total_records: totalRecords = 0, page = 1 } = {}
    } = this.props
    const { showdeleteAddOnsModal, showAddDeleteAddOnsModal } = this.state
    const columns = [
      {
        key: 'id',
        align: 'center',
        width: '80px',
        title: (
          <div style={{ textAlign: 'center' }}>
            <span>No.</span>
          </div>
        ),
        dataIndex: 's_no'
      },
      {
        key: 'add_ons_name',
        title: (
          <div>
            <span>Add-Ons Name</span>
          </div>
        ),
        dataIndex: 'name'
      },
      {
        key: 'edit_delete_add_ons',
        align: 'center',
        width: '120px',
        title: (
          <div>
            <span>Action</span>
          </div>
        ),
        dataIndex: 'name',
        render: (val) => {
          const currAddOn = addOnsQuestionsList.filter((ques) => {
            return ques.name === val
          }, [])
          const [{ is_active: isActive = true } = {}] = currAddOn || []
          return (
            <div style={{ display: 'flex', gap: '10px' }}>
              <img
                src={Edit}
                alt='edit'
                onClick={() => this.handleEditAddonsModal(val)}
              />
              {
              isActive && <img
                src={Delete}
                alt='delete'
                onClick={() => this.handleDeleteAddonsModal(val)}
                          />
            }
            </div>
          )
        }
      },
      {
        key: 'is_active',
        width: '150px',
        align: 'center',
        title: (
          <div>
            <span>Remarks</span>
          </div>
        ),
        dataIndex: 'is_active',
        render: (val) => {
          return <div style={val ? { color: '#009632', textAlign: 'center' } : { color: '#999999', textAlign: 'center' }}>{val === true ? 'Active' : 'Inactive'}</div>
        }
      }
    ]
    return (
      <LayoutContentWrapper
        className='referral-table'
        style={{
          color: '#788195'
        }}
      >
        {showdeleteAddOnsModal && <DeleteAddOns
          isOpen={showdeleteAddOnsModal}
          onCancel={this.handleCloseDeleteAddonsModal}
          onDelete={this.handleDeleteAddons}
          currQuestionsData={this.state.currQuestionsData}
          {...this.props}
                                  />}
        {showAddDeleteAddOnsModal && <AddEditAddOns
          isOpen={showAddDeleteAddOnsModal}
          onCancel={this.handleCloseAddEditAddonsModal}
          onSave={this.handleSaveAddEditAddonsModal}
          currQuestionsData={this.state.currQuestionsData}
          isEdit={this.state.isEdit}
          {...this.props}
                                     />}
        <LayoutContent>
          <Row
            style={{
              marginBottom: '10px'
            }}
            align='middle'
          >
            <div>
              <h3
                style={{
                  float: 'left',
                  fontWeight: '800'
                }}
              >
                Add-ons
              </h3>
              <div>
                <p
                  style={{
                    float: 'left',
                    color: '#4482FF',
                    marginLeft: '10px',
                    marginTop: '3px'
                  }}
                >
                  {totalRecords}
                </p>
              </div>
            </div>
            <div
              style={{
                float: 'right',
                display: 'flex'
              }}
            >
              <Button
                type='primary'
                style={{
                  background: '#FAF000',
                  borderColor: '#FAF000',
                  borderRadius: '8px',
                  padding: '16px, 32px, 16px, 32px',
                  fontWeight: '800',
                  height: '48px',
                  color: '#000000'
                }}
                onClick={() => this.handleAddAddonsModal()}
              >
                CREATE NEW ADD-ONS
              </Button>
            </div>
          </Row>
          <TableWrapper
            bordered={false}
            columns={columns}
            pagination={{
              pageSize: 10,
              total: totalRecords,
              current: page
            }}
            rowKey={(record) => record.id}
            dataSource={
              !getAddOnsListsError && !getAddOnsListsLoading
                ? addOnsQuestionsList
                : []
            }
            className='isAddOnTable table-striped-rows'
            loading={getAddOnsListsLoading}
            onChange={this.handleTableChange}
          />
        </LayoutContent>
      </LayoutContentWrapper>
    )
  }
}

AddOns.propTypes = {}

AddOns.defaultProps = {}

export default connect(
  (state) => ({
    userProducts: state.Auth.product,
    addOnsQuestionsList: state.Claims.addOnsQuestionsList,
    addOnsMetaData: state.Claims.addOnsMetaData,
    getAddOnsListsLoading: state.Loading.GET_ADD_ONS_QUESTIONS_LIST,
    getAddOnsListsError: state.Error.GET_ADD_ONS_QUESTIONS_LIST
  }),
  {
    getAddOnsQuestionnaireList
  }
)(AddOns)
