import React from 'react'
import { connect } from 'react-redux'
import { Button, Form, Modal, Row, Spin } from 'antd'
import {
  DeleteAddOnsModalWrapper,
  DeleteAddOnHeader,
  DeleteAddOnContent,
  DeleteAddOnWrapper,
  DeleteAddOnWrapperTitle,
  DeleteAddOnWrapperContent,
  DeleteAddOnQuestionsWrapper,
  DeleteAddOnQuestionsCtn,
  SubmitBtnCtn
} from './deleteAddOnsModal.style'
import claimActions from '../../redux/claims/actions'
import { showNotification } from '../../../components/ShowNotification'

const { deleteAddOnsRequest, resetReduxStateClaim } = claimActions
const FormItem = Form.Item

class DeleteAddOns extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      addOnData: [],
      loading: true,
      deleteLoading: false
    }
    this.initState = this.state
  }

  componentDidMount () {
    const { currQuestionsData = '', addOnsQuestionsList = [] } = this.props

    const currQuestion = addOnsQuestionsList.filter((ques) => {
      return ques.name === currQuestionsData
    }, [])
    this.setState({ addOnData: currQuestion, loading: false })
  }

  componentDidUpdate () {
    if (this.props.deleteAddOnsStatus === 'success') {
      const {
        onDelete = () => {},
        deleteAddOnsStatus,
        deleteAddOnsMessage = 'Error'
      } = this.props
      if (deleteAddOnsStatus === 'success') {
        showNotification('success', 'Add On Deleted Successfully')
        onDelete()
      } else if (deleteAddOnsStatus === 'error') {
        showNotification('error', deleteAddOnsMessage)
        onDelete()
      }
      this.setState({ deleteLoading: false })
      this.props.resetReduxStateClaim(['deleteAddOnsStatus'])
    }
  }

  handleCancel = () => {
    const { onCancel = () => {} } = this.props
    onCancel()
  };

  handleDelete = (name = '') => {
    if (name) {
      this.props.deleteAddOnsRequest({ addon_name: name })
    }
  };

  renderQuestionsList = () => {};

  render () {
    const { addOnData: [{ name = '', question_data: questionData = [] } = {}] = [] } =
      this.state
    return (
      <DeleteAddOnsModalWrapper>
        <Modal
          visible={this.props.isOpen}
          title='Delete Add-Ons'
          maskClosable={false}
          wrapClassName='delete-addons'
          onCancel={this.handleCancel}
          width={1200}
          footer={null}
        >
          <Spin spinning={this.state.loading} tip='Loading...'>
            <div>
              <DeleteAddOnHeader>
                Are you sure want to delete this Add-Ons?
              </DeleteAddOnHeader>
            </div>
            <DeleteAddOnContent>
              <DeleteAddOnWrapper>
                <div>
                  <Row>
                    <DeleteAddOnWrapperTitle>
                      Add-Ons Name
                    </DeleteAddOnWrapperTitle>
                    <DeleteAddOnWrapperContent>
                      {name}
                    </DeleteAddOnWrapperContent>
                  </Row>
                </div>
                <DeleteAddOnQuestionsWrapper>
                  {questionData?.map((question, ind) => {
                    const { display_text: displayText = '' } = question
                    return (
                      <DeleteAddOnQuestionsCtn key={ind}>
                        <DeleteAddOnWrapperTitle>
                          {`Question ${ind + 1}`}
                        </DeleteAddOnWrapperTitle>
                        <FormItem>
                          <DeleteAddOnWrapperContent>
                            {displayText}
                          </DeleteAddOnWrapperContent>
                        </FormItem>
                      </DeleteAddOnQuestionsCtn>
                    )
                  })}
                </DeleteAddOnQuestionsWrapper>
              </DeleteAddOnWrapper>
            </DeleteAddOnContent>
            <SubmitBtnCtn>
              <Button
                type='default'
                size='large'
                className='cancel-btns'
                onClick={this.handleCancel}
              >
                CANCEL
              </Button>
              <Button
                loading={this.state.deleteLoading}
                type='primary'
                size='large'
                className='delete-btn'
                disabled={false}
                onClick={() => {
                  this.handleDelete(name)
                  this.setState({ deleteLoading: true })
                }}
              >
                DELETE
              </Button>
            </SubmitBtnCtn>
          </Spin>
        </Modal>
      </DeleteAddOnsModalWrapper>
    )
  }
}

export default connect(
  (state) => ({
    getAddOnsListsError: state.Error.DELETE_ADD_ONS,
    deleteAddOnsStatus: state.Claims.deleteAddOnsStatus
  }),
  {
    deleteAddOnsRequest,
    resetReduxStateClaim
  }
)(DeleteAddOns)
