import React from 'react'
import { connect } from 'react-redux'
import { Button, Modal, Select, Form } from 'antd'
import {
  DeleteAddOnsModalWrapper,
  DeleteAddOnWrapperTitle,
  AddEditOnWrapperContent,
  AddEditOnQuestionsWrapper,
  AddEditOnQuestionsCtn,
  SubmitBtnCtn,
  EditAddOnsInput,
  AddEditOnWrapperTitle,
  AddAddOnsInput,
  AddOnQuestionsDeleteCtn,
  DeleteImageCtn,
  SelectCtn
} from './deleteAddOnsModal.style'
import claimActions from '../../redux/claims/actions'
import { showNotification } from '../../../components/ShowNotification'
import CircularLoader from '../../../components/CircularLoader'
import Delete from '../../../image/delete-icon.png'

const { Option } = Select
const FormItem = Form.Item
const { resetReduxStateClaim, getQuestionnaireList, UpdateEditAddOnsRequest } =
  claimActions

class AddEditAddOns extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      user: {},
      loading: true,
      questionsList: [],
      count: 1,
      addOnName: '',
      questionsResponse: [],
      questionData: [],
      editAddLoading: false
    }
    this.initState = this.state
  }

  componentDidMount () {
    this.props.getQuestionnaireList({ active: true })
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      currQuestionsData = '',
      addOnsQuestionsList = [],
      questionsList = [],
      isEdit = false,
      editUpdateAddOnsStatus,
      onSave = () => {},
      onCancel = () => {},
      editUpdateAddOnsMessage = ''
    } = nextProps

    if (isEdit) {
      let questionsRes = []
      const currQuestion = addOnsQuestionsList.filter((ques) => {
        if (ques.name === currQuestionsData) {
          questionsRes = ques.question_data?.map((i) => i.id, [])
        }
        return ques.name === currQuestionsData
      }, [])

      const questionsidMap = questionsList?.reduce((prev, curr) => {
        const { id = '', display_text: displayText = '' } = curr
        return { ...prev, [id]: displayText }
      }, {})

      this.setState({
        loading: false,
        count: currQuestion[0]?.question_data?.length || 1,
        questionsResponse: questionsRes,
        questionsidMap: questionsidMap,
        addOnName: currQuestion[0]?.name
      })
    } else {
      const questionsidMap = questionsList?.reduce((prev, curr) => {
        const { id = '', display_text: displayText = '' } = curr
        return { ...prev, [id]: displayText }
      }, {})
      this.setState({
        questionsList: [],
        questionData: [],
        questionsidMap
      })
    }

    if (editUpdateAddOnsStatus === 'success') {
      const msg = isEdit ? 'Updated Successfully' : 'Add On Successfully Added'
      showNotification('success', msg)
      this.props.getQuestionnaireList({ active: true })
      onSave()
      onCancel()
      this.setState({ editAddLoading: false })
    } else if (editUpdateAddOnsStatus === 'error') {
      const Error = editUpdateAddOnsMessage || 'Error'
      showNotification('error', Error)
      onCancel()
      this.setState({ editAddLoading: false })
    }

    this.props.resetReduxStateClaim(['editUpdateAddOnsStatus'])
  }

  handleCancel = () => {
    const { onCancel = () => {} } = this.props
    onCancel()
  };

  onSubmit = async (e) => {
    e.preventDefault()
    const { user: { name: userName = '' } = {}, isEdit = false } = this.props
    const { addOnName = '', questionsResponse = [] } = this.state

    const payload = isEdit
      ? {
          question_ids: [...new Set(questionsResponse)],
          addon_name: addOnName,
          updated_by: userName,
          is_update: true
        }
      : {
          question_ids: [...new Set(questionsResponse)],
          addon_name: addOnName,
          updated_by: userName
        }

    this.props.UpdateEditAddOnsRequest(payload)
  };

  handleQuestionClick = (ind, id) => {
    const { questionsResponse = [] } = this.state
    if (questionsResponse.includes(id)) {
      showNotification('error', 'Question Already Added')
    } else {
      const updatedRes = this.state.questionsResponse
      updatedRes[ind] = id
      this.setState({ questionsResponse: [...updatedRes] })
    }
  };

  handleDeleteQuestions = (id) => {
    const { questionsResponse = [], count = 1 } = this.state
    const qId = questionsResponse[id]

    if (qId) {
      const updatedQuestionsIDs = questionsResponse.filter((quesId) => {
        return quesId !== qId
      })
      this.setState({
        questionsResponse: updatedQuestionsIDs,
        count: count - 1
      })
    } else {
      this.setState({
        count: count - 1
      })
    }
  };

  handleAddonNameChange = (e) => {
    const name = e.target.value
    this.setState({ addOnName: name })
  };

  render () {
    const {
      isEdit = false,
      questionsListLoading = true,
      questionsList = []
    } = this.props
    const {
      questionsidMap = {},
      questionsResponse = [],
      addOnName,
      count
    } = this.state
    const { getFieldDecorator } = this.props.form
    const isDisabled = addOnName && this.state.questionsResponse.length

    const noOfQuestions = new Array(count).fill(true)

    return (
      <DeleteAddOnsModalWrapper>
        <Modal
          visible={this.props.isOpen}
          title={isEdit ? 'Update Add-Ons' : 'Create New Add-Ons'}
          maskClosable={false}
          wrapClassName='delete-addons'
          onCancel={this.handleCancel}
          width={1200}
          footer={[
            <SubmitBtnCtn key={1}>
              <FormItem>
                <Button
                  type='default'
                  size='large'
                  className='cancel-btns'
                  onClick={this.handleCancel}
                >
                  CANCEL
                </Button>
              </FormItem>
              <FormItem>
                <Button
                  form='event-form'
                  htmlType='submit'
                  key='submit'
                  type='primary'
                  size='large'
                  className='save-btn'
                  disabled={!isDisabled}
                  onClick={() => this.setState({ editAddLoading: true })}
                  loading={this.state.editAddLoading}
                >
                  {isEdit ? 'UPDATE' : 'ADD'}
                </Button>
              </FormItem>
            </SubmitBtnCtn>
          ]}
          bodyStyle={{ overflowY: 'auto' }}
        >
          <CircularLoader isSpining={questionsListLoading}>
            <Form
              id='event-form'
              style={{
                marginTop: '10px'
              }}
              onSubmit={(e) => {
                this.onSubmit(e)
              }}
            >
              <FormItem validateStatus='validateStatus'>
                {getFieldDecorator('add_on', {
                  rules: [
                    {
                      required: true,
                      message: 'Please Input Add On Name'
                    }
                  ]
                })(
                  <div>
                    <DeleteAddOnWrapperTitle>
                      Add-Ons Name
                    </DeleteAddOnWrapperTitle>
                    {isEdit
                      ? (
                        <AddAddOnsInput>{addOnName}</AddAddOnsInput>
                        )
                      : (
                        <AddEditOnWrapperContent>
                          <EditAddOnsInput
                            placeholder='Input Add-Ons Name'
                            onChange={this.handleAddonNameChange}
                          />
                        </AddEditOnWrapperContent>
                        )}
                  </div>
                )}
              </FormItem>
              <AddEditOnQuestionsWrapper>
                {count !== 0 &&
                  noOfQuestions.map(
                    (item, ind) => {
                      return (
                        <AddEditOnQuestionsCtn key={ind}>
                          <AddEditOnWrapperTitle>
                            Question {ind + 1}
                          </AddEditOnWrapperTitle>
                          <AddOnQuestionsDeleteCtn isEdit={isEdit}>
                            <SelectCtn>
                              <Select
                                showSearch
                                className='form-select-width'
                                style={{ height: '56px' }}
                                placeholder='Select Question'
                                optionFilterProp='children'
                                disabled={false}
                                value={questionsidMap[questionsResponse[ind]]}
                              >
                                {questionsList &&
                                  questionsList.filter(({ id }) => !questionsResponse.includes(id)).map(
                                    ({ display_text: displayText, id }) => (
                                      <Option
                                        key={id}
                                        onClick={() =>
                                          this.handleQuestionClick(ind, id)}
                                      >
                                        {displayText}
                                      </Option>
                                    )
                                  )}
                              </Select>
                            </SelectCtn>
                            {isEdit && (
                              <DeleteImageCtn>
                                <img
                                  src={Delete}
                                  alt='delete'
                                  onClick={() =>
                                    this.handleDeleteQuestions(ind)}
                                  height='56px'
                                  width='56px'
                                />
                              </DeleteImageCtn>
                            )}
                          </AddOnQuestionsDeleteCtn>
                        </AddEditOnQuestionsCtn>
                      )
                    }
                  )}
                <AddEditOnQuestionsCtn>
                  <AddEditOnWrapperTitle>
                    Question {this.state.count + 1}
                  </AddEditOnWrapperTitle>
                  <FormItem>
                    <div
                      className='add-questions-btn'
                      onClick={() =>
                        this.setState({ count: this.state.count + 1 })}
                    >
                      ATTACH MORE QUESTIONS
                    </div>
                  </FormItem>
                </AddEditOnQuestionsCtn>
              </AddEditOnQuestionsWrapper>
            </Form>
          </CircularLoader>
        </Modal>
      </DeleteAddOnsModalWrapper>
    )
  }
}

const WrappedAddEditAddOns = Form.create()(AddEditAddOns)

export default connect(
  (state) => ({
    questionsList: state.Claims.questionsList,
    questionsListLoading: state.Loading.GET_QUESTIONS_LIST,
    questionsListError: state.Error.GET_QUESTIONS_LIST,
    editUpdateAddOnsStatus: state.Claims.editUpdateAddOnsStatus,
    editUpdateAddOnsMessage: state.Claims.editUpdateAddOnsMessage,
    user: state.Auth.profile
  }),
  {
    resetReduxStateClaim,
    getQuestionnaireList,
    UpdateEditAddOnsRequest
  }
)(WrappedAddEditAddOns)
